def second_highest(scores):
    # Find the highest and second highest distinct values
    highest = None
    second = None
    for score in scores:
        if highest is None or score > highest:
            # New highest found; old highest becomes candidate for second
            if highest is not None and highest != score:
                second = highest
            highest = score
        elif score != highest:
            # score is less than highest but could be second
            if second is None or score > second:
                second = score
    return second

print(second_highest([3, 1, 4, 1, 5]))

